import { describe, expect, test } from 'bun:test';
import { resolve } from 'node:path';
import { OperatorRuntime } from '@agentic-ddd/runtime';
import { FakeLlm, covers } from '@agentic-ddd/testing';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';
import { CreateTask } from '../application/create-task';
import { CompleteTask } from '../application/complete-task';
import { TaskOperator } from '../operators/task.operator';

const root = resolve(import.meta.dir, '../..');

describe('task-operator', () => {
  test(covers(['operator:task-operator', 'criterion:0001/tools'], 'cria e conclui a tarefa usando só suas duas tools e publica os dois eventos'), async () => {
    const repo = new InMemoryTaskRepository();
    const llm = new FakeLlm([
      { stopReason: 'tool_calls', content: [{ type: 'tool_call', id: 'a', name: 'create_task', input: { task_id: 't1', title: 'Escrever testes' } }] },
      { stopReason: 'tool_calls', content: [{ type: 'tool_call', id: 'b', name: 'complete_task', input: { task_id: 't1' } }] },
      { stopReason: 'end', content: [{ type: 'text', text: 'Tarefa criada e concluída.' }] },
    ]);
    const runtime = new OperatorRuntime({ llm, root, modules: [{ name: 'tasks', path: 'app' }] });
    const seen: string[] = [];
    runtime.eventBus.subscribe((event) => { seen.push(event.name); });
    await runtime.register(TaskOperator, new Map<any, any>([[CreateTask, new CreateTask(repo)], [CompleteTask, new CompleteTask(repo)]]));

    const result = await runtime.run('task-operator', { message: 'Crie a tarefa t1 e conclua-a.' });

    expect(result.status).toBe('completed');
    expect(result.output).toBe('Tarefa criada e concluída.');
    expect(llm.requests[0]!.tools.map((t) => t.name)).toEqual(['complete_task', 'create_task']);
    expect((await repo.findById('t1'))!.status).toBe('completed');
    expect(result.events.map((e) => e.name)).toEqual(['TaskCreated', 'TaskCompleted']);
    expect(seen).toEqual(['TaskCreated', 'TaskCompleted']);
  });
});
